package com.bn5212.mimic.common;
import jakarta.servlet.http.HttpServletRequest; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestControllerAdvice public class GlobalExceptionHandler { @ExceptionHandler(IllegalArgumentException.class) ResponseEntity<ErrorResponse> bad(IllegalArgumentException e,HttpServletRequest r){return ResponseEntity.badRequest().body(new ErrorResponse("bad_request",e.getMessage(),(String)r.getAttribute(RequestIdFilter.HEADER)));} @ExceptionHandler(IllegalStateException.class) ResponseEntity<ErrorResponse> unavailable(IllegalStateException e,HttpServletRequest r){return ResponseEntity.status(503).body(new ErrorResponse("model_unavailable",e.getMessage(),(String)r.getAttribute(RequestIdFilter.HEADER)));} @ExceptionHandler(Exception.class) ResponseEntity<ErrorResponse> error(Exception e,HttpServletRequest r){return ResponseEntity.status(500).body(new ErrorResponse("internal_error","Unexpected server error",(String)r.getAttribute(RequestIdFilter.HEADER)));} }
